proof fn suffix_add<T>(ex: Execution<T>, a: nat, b: nat)
    ensures ex.suffix(a).suffix(b) == ex.suffix(a + b)
{
    assert forall |k: nat| #[trigger] (ex.suffix(a).suffix(b).nat_to_state)(k) == (ex.suffix(a + b).nat_to_state)(k) by {};
    execution_equality(ex.suffix(a).suffix(b), ex.suffix(a + b));
}

proof fn always_p_or_eventually_q<T>(ex: Execution<T>, next: TempPred<T>, p: TempPred<T>, q: TempPred<T>)
    requires
        always(p.and(next).implies(later(p).or(later(q)))).satisfied_by(ex),
        always(next).satisfied_by(ex),
    ensures always(p.implies(always(p).or(eventually(q)))).satisfied_by(ex),
{
    assert forall |j: nat| (p.implies(always(p).or(eventually(q)))).satisfied_by(#[trigger] ex.suffix(j)) by {
        if p.satisfied_by(ex.suffix(j)) {
            // Propagate always predicates to ex.suffix(j)
            always_propagate_forwards(ex, p.and(next).implies(later(p).or(later(q))), j);
            always_propagate_forwards(ex, next, j);
            // Unfold always at ex.suffix(j)
            always_unfold(ex.suffix(j), p.and(next).implies(later(p).or(later(q))));
            always_unfold(ex.suffix(j), next);

            if !eventually(q).satisfied_by(ex.suffix(j)) {
                not_eventually_unfold(ex.suffix(j), q);
                // q never holds anywhere after ex.suffix(j)

                // Establish the step condition for always_p_or_eventually_q_rec
                assert forall |idx: nat|
                    p.satisfied_by(ex.suffix(j).suffix(idx)) && next.satisfied_by(ex.suffix(j).suffix(idx)) ==>
                    p.satisfied_by(ex.suffix(j).suffix(idx + 1)) || q.satisfied_by(ex.suffix(j).suffix(idx + 1))
                by {
                    if p.satisfied_by(ex.suffix(j).suffix(idx)) && next.satisfied_by(ex.suffix(j).suffix(idx)) {
                        // p.and(next) satisfied at ex.suffix(j).suffix(idx)
                        implies_apply(ex.suffix(j).suffix(idx), p.and(next), later(p).or(later(q)));
                        // Now (later(p).or(later(q))).satisfied_by(ex.suffix(j).suffix(idx))
                        // = p.satisfied_by(ex.suffix(j).suffix(idx).suffix(1)) || q.satisfied_by(...)
                        // Use suffix_add to rewrite .suffix(idx).suffix(1) as .suffix(idx + 1)
                        suffix_add(ex.suffix(j), idx, 1);
                        // ex.suffix(j).suffix(idx).suffix(1) == ex.suffix(j).suffix(idx + 1)
                    }
                };

                // Now prove always(p) at ex.suffix(j)
                assert forall |i: nat| p.satisfied_by(#[trigger] ex.suffix(j).suffix(i)) by {
                    always_p_or_eventually_q_rec(ex.suffix(j), next, p, q, i);
                };
                assert always(p).satisfied_by(ex.suffix(j));
            }
            // In both branches, always(p).or(eventually(q)) holds
        }
    };
}

}

